//! Grammar points and example sentences (generated by pipeline/build.py).

use crate::i18n::Lang;
use serde::Deserialize;
use std::collections::HashMap;

/// `[text, reading]`; reading is empty for kana-only parts.
#[derive(Debug, Clone, Deserialize)]
pub struct Seg(pub String, pub String);

#[derive(Debug, Clone, Default, Deserialize)]
pub struct Sentence {
    pub id: u64,
    pub ja: String,
    pub en: String,
    #[serde(default)]
    pub owner: String,
    pub furi: Vec<Seg>,
    /// Character (not byte) offsets of the blank.
    pub cloze: [usize; 2],
    pub answers: Vec<String>,
    pub hint: Option<String>,
    /// "app" for example sentences written for this app (not from Tatoeba).
    #[serde(default)]
    pub src: String,
    /// French translation (empty if none).
    #[serde(default)]
    pub fr: String,
    /// Tatoeba id and contributor of the French translation (when it comes from Tatoeba).
    #[serde(default)]
    pub fr_id: u64,
    #[serde(default)]
    pub fr_owner: String,
    /// "app" when the French translation was written for this app.
    #[serde(default)]
    pub fr_src: String,
    /// Dictionary forms of the sentence's content words (for dictionary lookups).
    #[serde(default)]
    pub words: Vec<String>,
    /// The answer's tokens in kana, each marked "p" (particle), "v" (conjugating) or "o" (other);
    /// only for answers of more than one token. Used for "almost" hints.
    #[serde(default)]
    pub parts: Vec<(String, String)>,
    /// Answers (kana) using another grammar point that fits here too (から for ので ...): possible,
    /// but not the point being practised.
    #[serde(default)]
    pub alts: Vec<String>,
}

impl Sentence {
    /// Translation in `lang` (English if there is no French one).
    pub fn translation(&self, lang: Lang) -> &str {
        match lang {
            Lang::Fr if !self.fr.is_empty() => &self.fr,
            _ => &self.en,
        }
    }

    /// Credit line shown under the sentence: the original Japanese sentence and, in French,
    /// where the translation comes from.
    pub fn attribution(&self, lang: Lang) -> String {
        let fr = lang == Lang::Fr;
        if self.src == "app" {
            return if fr { "Exemple écrit pour cette appli" } else { "Example written for this app" }.into();
        }
        let original = match (self.owner.is_empty(), fr) {
            (true, _) => format!("Tatoeba #{}", self.id),
            (false, false) => format!("Tatoeba #{} by {}", self.id, self.owner),
            (false, true) => format!("Tatoeba #{} par {}", self.id, self.owner),
        };
        if !fr || self.fr.is_empty() {
            original
        } else if self.fr_src == "app" {
            format!("{original} · traduction écrite pour cette appli")
        } else if self.fr_owner.is_empty() {
            format!("{original} · trad. #{}", self.fr_id)
        } else {
            format!("{original} · trad. #{} par {}", self.fr_id, self.fr_owner)
        }
    }

    /// Hint under the blank ("食べる（たべる） · past, negative") with the grammatical tags in `lang`.
    pub fn hint(&self, lang: Lang) -> Option<String> {
        let h = self.hint.as_ref()?;
        Some(match (lang, h.split_once(" · ")) {
            (Lang::Fr, Some((word, tags))) => {
                let tags: Vec<&str> = tags.split(", ").map(|t| crate::i18n::tr(lang, t)).collect();
                format!("{word} · {}", tags.join(", "))
            }
            _ => h.clone(),
        })
    }
}

impl Sentence {
    pub fn answer(&self) -> String {
        self.ja.chars().skip(self.cloze[0]).take(self.cloze[1] - self.cloze[0]).collect()
    }
}

#[derive(Debug, Clone, Deserialize)]
pub struct GrammarPoint {
    pub id: String,
    pub level: String,
    pub order: usize,
    pub title: String,
    pub meaning: String,
    pub structure: String,
    pub explanation: String,
    pub sentences: Vec<Sentence>,
    /// French texts (written for this app).
    #[serde(default)]
    pub fr: Option<PointText>,
    /// What this point adds compared with others that could take its place (English, French).
    #[serde(default)]
    pub nuance: Option<(String, String)>,
}

#[derive(Debug, Clone, Deserialize)]
pub struct PointText {
    pub title: String,
    pub meaning: String,
    pub structure: String,
    pub explanation: String,
}

impl GrammarPoint {
    fn french(&self, lang: Lang) -> Option<&PointText> {
        self.fr.as_ref().filter(|_| lang == Lang::Fr)
    }
    pub fn title_in(&self, lang: Lang) -> &str {
        self.french(lang).map_or(&self.title, |f| &f.title)
    }
    pub fn meaning_in(&self, lang: Lang) -> &str {
        self.french(lang).map_or(&self.meaning, |f| &f.meaning)
    }
    pub fn structure_in(&self, lang: Lang) -> &str {
        self.french(lang).map_or(&self.structure, |f| &f.structure)
    }
    pub fn explanation_in(&self, lang: Lang) -> &str {
        self.french(lang).map_or(&self.explanation, |f| &f.explanation)
    }
}

#[derive(Debug, Deserialize)]
pub struct Content {
    pub source: String,
    #[serde(default)]
    pub source_fr: String,
    pub points: Vec<GrammarPoint>,
    #[serde(skip)]
    index: HashMap<String, usize>,
}

/// The bundled content file, embedded at compile time.
pub const BUNDLED: &str = include_str!("../../../data/build/content.json");

impl Content {
    pub fn parse(json: &str) -> serde_json::Result<Content> {
        let mut c: Content = serde_json::from_str(json)?;
        c.points.retain(|p| !p.sentences.is_empty());
        c.points.sort_by_key(|p| p.order);
        c.index = c.points.iter().enumerate().map(|(i, p)| (p.id.clone(), i)).collect();
        Ok(c)
    }

    pub fn bundled() -> Content {
        Self::parse(BUNDLED).expect("bundled content.json is valid")
    }

    /// Credits line for the example sentences.
    pub fn source_in(&self, lang: Lang) -> &str {
        if lang == Lang::Fr && !self.source_fr.is_empty() { &self.source_fr } else { &self.source }
    }

    pub fn get(&self, id: &str) -> Option<&GrammarPoint> {
        self.index.get(id).map(|&i| &self.points[i])
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn sentence(extra: &str) -> Sentence {
        serde_json::from_str(&format!(
            r#"{{"id":4771,"ja":"無理だ。","en":"It's impossible.","owner":"bunbuku","furi":[],
                "cloze":[2,3],"answers":["だ"],"hint":"食べる（たべる） · past, negative"{extra}}}"#
        ))
        .unwrap()
    }

    #[test]
    fn translation_falls_back_to_english() {
        let s = sentence("");
        assert_eq!(s.translation(Lang::Fr), "It's impossible.");
        let s = sentence(r#","fr":"C'est impossible.","fr_id":12,"fr_owner":"TRANG""#);
        assert_eq!(s.translation(Lang::Fr), "C'est impossible.");
        assert_eq!(s.translation(Lang::En), "It's impossible.");
    }

    #[test]
    fn french_credits_the_original_and_the_translation() {
        let s = sentence(r#","fr":"C'est impossible.","fr_id":12,"fr_owner":"TRANG""#);
        assert_eq!(s.attribution(Lang::En), "Tatoeba #4771 by bunbuku");
        assert_eq!(s.attribution(Lang::Fr), "Tatoeba #4771 par bunbuku · trad. #12 par TRANG");
        let s = sentence(r#","fr":"C'est impossible.","fr_src":"app""#);
        assert_eq!(s.attribution(Lang::Fr), "Tatoeba #4771 par bunbuku · traduction écrite pour cette appli");
        let s = sentence(r#","src":"app","fr":"C'est impossible.","fr_src":"app""#);
        assert_eq!(s.attribution(Lang::Fr), "Exemple écrit pour cette appli");
        assert_eq!(s.attribution(Lang::En), "Example written for this app");
    }

    #[test]
    fn hint_tags_are_translated() {
        let s = sentence("");
        assert_eq!(s.hint(Lang::Fr).unwrap(), "食べる（たべる） · passé, négatif");
        assert_eq!(s.hint(Lang::En).unwrap(), "食べる（たべる） · past, negative");
    }

    #[test]
    fn point_texts_fall_back_to_english() {
        let mut p: GrammarPoint = serde_json::from_str(
            r#"{"id":"da","level":"N5","order":0,"title":"だ","meaning":"is","structure":"Noun + だ",
                "explanation":"だ is the casual copula.","sentences":[]}"#,
        )
        .unwrap();
        assert_eq!(p.meaning_in(Lang::Fr), "is");
        p.fr = Some(PointText {
            title: "だ".into(),
            meaning: "être".into(),
            structure: "Nom + だ".into(),
            explanation: "だ est la copule familière.".into(),
        });
        assert_eq!(p.meaning_in(Lang::Fr), "être");
        assert_eq!(p.structure_in(Lang::Fr), "Nom + だ");
        assert_eq!(p.explanation_in(Lang::En), "だ is the casual copula.");
    }
}
